int find(const char *names[], int n,
         const char *t) {
    for (int i = 0; i < n; i++) {
        if (strcmp(names[i], t) == 0) {
            return i;
        }
    }
    return -1;
}

struct person {
    char name[16];
    int phone;
};
int lookup(struct person p[], int n,
           const char *t) {
    for (int i = 0; i < n; i++)
        if (strcmp(p[i].name, t) == 0)
            return p[i].phone;
    return -1;
}
